private const val MIN_INT: Int = Int.MIN_VALUE
private val MAX_UINT: UInt = UInt.MAX_VALUE
private val MIN_UINT: UInt = UInt.MIN_VALUE

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c: Int
        do {
            c = readByte()
            if (c == -1) throw NoSuchElementException("Unexpected end of input")
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var result = 0L
        while (c > 32 && c != -1) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return if (sign == 1) result else -result
    }

    fun nextInt(): Int = nextLong().toInt()
}

